<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import * as echarts from 'echarts'
type Target={id:number;target_type:string;target_key:string;title:string;description:string;cover_url:string;interval_seconds:number;last_collected_at?:string;last_success_at?:string;last_error_at?:string;next_collect_at?:string;last_error:string;active:boolean}
const query=ref(''),targets=ref<Target[]>([]),history=ref<Target[]>([]),selected=ref<Target|null>(null),preview=ref<any>(null),previewStats=ref<any>(null),trend=ref<any>(null),loading=ref(false),error=ref(''),chartEl=ref<HTMLElement|null>(null),chart=ref<any>(null),chartMode=ref<'growth'|'total'>('growth'),showSettings=ref(false),interval=ref(60)
const fields=computed(()=>selected.value?.target_type==='video'?[['view_count','播放'],['like_count','点赞'],['coin_count','投币'],['favorite_count','收藏'],['reply_count','评论'],['danmaku_count','弹幕'],['online_count','在线']]:[['follower_count','粉丝'],['video_count','投稿']])
async function api(path:string,options?:RequestInit){const r=await fetch(path,options);const d=await r.json();if(!r.ok)throw Error(d.detail||'请求失败');return d}
async function load(){[targets.value,history.value]=await Promise.all([api('/api/targets'),api('/api/targets/history')])}
async function search(){if(!query.value.trim())return;loading.value=true;error.value='';try{preview.value=await api('/api/targets/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({value:query.value})})}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function viewOnce(){if(!preview.value)return;loading.value=true;try{const d=await api('/api/targets/view-once',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...preview.value,interval_seconds:60})});previewStats.value=d.stats;selected.value={...preview.value,id:0,active:false,last_error:'',interval_seconds:60};preview.value=null;trend.value={points:[{time:new Date().toISOString(),...d.stats}],latest:{time:new Date().toISOString(),...d.stats},growth:{}};await nextTick();draw()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function startMonitoring(){if(!preview.value)return;loading.value=true;try{const t=await api('/api/targets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...preview.value,interval_seconds:60})});preview.value=null;await load();selected.value=targets.value.find(x=>x.id===t.id)||t;await refresh()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function restore(t:Target){loading.value=true;try{const active=await api('/api/targets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_type:t.target_type,target_key:t.target_key,interval_seconds:60})});await load();selected.value=targets.value.find(x=>x.id===active.id)||active;await refresh()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function refresh(){if(!selected.value||selected.value.id===0)return;const group=selected.value.target_type==='video'?'videos':'uploaders';try{trend.value=await api(`/api/${group}/${selected.value.id}/trend?hours=24`);await nextTick();draw()}catch(e:any){error.value=e.message}}
function draw(){if(!chartEl.value||!trend.value)return;chart.value?.dispose();chart.value=echarts.init(chartEl.value);const points=trend.value.points;const fmt=(v:number)=>Math.abs(v)>=10000?`${(v/10000).toFixed(1)}万`:Math.abs(v)>=1000?`${(v/1000).toFixed(1)}千`:String(Math.round(v));chart.value.setOption({tooltip:{trigger:'axis',valueFormatter:(v:any)=>fmt(Number(v))},legend:{top:0},grid:{left:78,right:20,bottom:35,top:35},xAxis:{type:'category',data:points.map((p:any)=>new Date(p.time).toLocaleTimeString())},yAxis:{type:'value',name:chartMode.value==='growth'?'增长':'总量',axisLabel:{formatter:fmt}},series:fields.value.map(([key,name])=>({name,type:'line',smooth:true,showSymbol:false,data:points.map((p:any)=>chartMode.value==='growth'?(p[key]==null?null:(p[key]||0)-(points[0][key]||0)):p[key])}))})}
function select(t:Target){selected.value=t;refresh()}
async function remove(t:Target){if(!window.confirm(`确定停止监控“${t.title||t.target_key}”吗？\n\n历史数据不会删除。`))return;await api(`/api/targets/${t.id}`,{method:'DELETE'});if(selected.value?.id===t.id){selected.value=null;trend.value=null}await load()}
async function collectNow(){if(!selected.value||selected.value.id===0)return;loading.value=true;try{const d=await api(`/api/targets/${selected.value.id}/collect`,{method:'POST'});selected.value=d.target;await load();await refresh()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function saveSettings(){if(!selected.value)return;try{selected.value=await api(`/api/targets/${selected.value.id}/settings`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({interval_seconds:Number(interval.value)})});showSettings.value=false}catch(e:any){error.value=e.message}}
let timer:any;onMounted(async()=>{await load();timer=setInterval(()=>{if(selected.value?.active)refresh()},60000)});onUnmounted(()=>{clearInterval(timer);chart.value?.dispose()})
</script>
<template><main><header><div class="brand">BilibiliMonitor<span>本地数据观察</span></div><form @submit.prevent="search"><input v-model="query" placeholder="输入 BV / AV / 视频链接 / UID / 空间链接"/><button :disabled="loading">{{loading?'读取中…':'搜索'}}</button></form><p class="hint">搜索后先确认是否加入监控；后台自动采集，页面每分钟更新。</p></header><p v-if="error" class="search-error">{{error}} <button @click="error=''">关闭</button></p><section v-if="!targets.length&&!history.length&&!selected" class="empty"><div class="orb">◌</div><h1>从一个视频或 UP 主开始</h1><p>搜索后再决定是否加入监控，页面不会预先堆满数据。</p></section><section v-else class="layout"><aside><h3>正在监控 <small>{{targets.length}}</small></h3><button v-for="t in targets" :key="t.id" class="target" :class="{active:selected?.id===t.id}" @click="select(t)"><b>{{t.title||t.target_key}}</b><small>{{t.target_type==='video'?'视频':'UP 主'}} · {{t.target_key}}</small><i @click.stop="remove(t)">×</i></button><h3 class="history-title">历史记录 <small>{{history.length}}</small></h3><button v-for="t in history" :key="'h'+t.id" class="target history-target" :class="{active:selected?.id===t.id}" @click="select(t)"><b>{{t.title||t.target_key}}</b><small>{{t.target_type==='video'?'视频':'UP 主'}} · 已停止</small><i @click.stop="restore(t)">↻</i></button></aside><article v-if="selected"><div class="title"><div><small>{{selected.target_type==='video'?'视频':'UP 主'}} · {{selected.target_key}}</small><h1>{{selected.title||selected.target_key}}</h1></div><div><span class="live" v-if="selected.active">● 自动采集中</span><span class="stopped" v-else>历史记录 / 仅查看</span></div></div><div class="metrics"><div v-for="([key,name]) in fields" :key="key" class="metric"><small>{{name}}</small><strong>{{trend?.latest?.[key]??'—'}}</strong><em>{{trend?.growth?.[key]>0?'+':''}}{{trend?.growth?.[key]??0}}</em></div></div><div class="toolbar"><button v-if="selected.active" @click="collectNow">立即采集</button><button v-if="selected.active" class="secondary" @click="showSettings=true">采集设置</button><small>最近成功：{{selected.last_success_at?new Date(selected.last_success_at).toLocaleString():'暂无'}}</small><small v-if="selected.last_error">最近错误：{{selected.last_error}}</small></div><div class="panel"><div class="panel-head"><div><h2>最近 24 小时趋势</h2><small>{{chartMode==='growth'?'显示相对首次采集的增长量':'显示指标绝对总量'}}</small></div><div class="chart-tabs"><button :class="{chosen:chartMode==='growth'}" @click="chartMode='growth';draw()">增量</button><button :class="{chosen:chartMode==='total'}" @click="chartMode='total';draw()">总量</button></div></div><div ref="chartEl" class="chart" v-if="trend?.points?.length"></div><div class="no-data" v-else>暂无历史记录。</div></div></article></section><div v-if="preview" class="modal-backdrop"><div class="modal"><div class="modal-icon">◉</div><h2>找到{{preview.target_type==='video'?'视频':'UP 主'}}</h2><h3>{{preview.title||preview.target_key}}</h3><p>{{preview.target_type==='video'?'视频':'UP 主'}} · {{preview.target_key}}</p><p class="modal-question">是否加入后台自动监控？</p><div class="modal-actions"><button class="secondary" @click="viewOnce">仅查看一次</button><button @click="startMonitoring">开始监控</button></div><button class="cancel" @click="preview=null">取消</button></div></div><div v-if="showSettings" class="modal-backdrop"><div class="modal"><h2>采集设置</h2><p>采集间隔（秒）</p><input v-model.number="interval" type="number" min="60" step="60"/><div class="modal-actions"><button class="secondary" @click="showSettings=false">取消</button><button @click="saveSettings">保存</button></div></div></div></main></template>
